import React from 'react';
import { Link } from 'react-router-dom';

function LandingPage() {
    return (
        <div style={{ textAlign: 'center', marginTop: '50px' }}>
            <h1 style={{ color: '#4CAF50' }}>Welcome</h1>
            <p style={{ fontSize: '18px' }}>Please choose an option:</p>
            <Link to="/login" style={{ margin: '10px', textDecoration: 'none', color: '#2196F3' }}>Login</Link>
            <br />
            <Link to="/step1" style={{ margin: '10px', textDecoration: 'none', color: '#2196F3' }}>Register</Link>
        </div>
    );
}

export default LandingPage;
